+export function createCarSearch(query) {
+  const normalize = text => text.normalize('NFKC').toLowerCase();
+  const words = text => normalize(text).replace(/[^\p{L}\p{N}]+/gu, ' ').trim().split(/\s+/).filter(Boolean);
